Given a root of the binary tree, return the postorder traversal of the binary tree.Postorder Traversal is a method to traverse a tree such that for each node, you first traverse its left subtree, then its right subtree, and finally visit the node itself.Examples:Input: Output: [2, 3, 1]Explanation: Postorder Traversal visits the nodes in the following order: Left, Right, Root. Therefore, we visit the left node 2, then the right node 3 and lastly the root node 1.Input: Output: [4, 5, 2, 6, 3, 1]Explanation: Postorder Traversal visits the nodes in the following order: Left, Right, Root. Therefore resulting is 4 , 5, 2, 6, 3, 1.Try It Yourself[Approach] Using RecursionThe main idea is to traverse the tree recursively, starting from the root node, and first completely traverse the left subtree, then completely traverse the right subtree, and finally visit the root node.How does Postorder Traversal work?
            C++

    #include <iostream>
#include <vector>
using namespace std;

// Node Structure
class Node {
public:
    int data;
    Node *left;
    Node *right;

    Node(int v)
    {
        data = v;
        left = right = nullptr;
    }
};

void postOrder(Node *node, vector<int> &res)
{
    if (node == nullptr)
        return;

    // First we traverse left subtree
    postOrder(node->left, res);

    // After visiting left, traverse right subtree
    postOrder(node->right, res);

    // now we visit node
    res.push_back(node->data);
}

int main()
{
    //Represent Tree
    //       1
    //      / \
    //     2   3
    //    / \   \
    //   4   5   6
    Node *root = new Node(1);
    root->left = new Node(2);
    root->right = new Node(3);
    root->left->left = new Node(4);
    root->left->right = new Node(5);
    root->right->right = new Node(6);

    vector<int> result;
    postOrder(root, result); 

    // Print the postorder
    for (int val : result)
        cout << val << " ";

    return 0;
}


            C

    #include <stdio.h>
#include <stdlib.h>

// Node Structure
struct Node {
    int data;
    struct Node *left;
    struct Node *right;
};

struct Node* createNode(int v)
{
    struct Node* node = (struct Node*)malloc(sizeof(struct Node));
    node->data = v;
    node->left = NULL;
    node->right = NULL;
    return node;
}

void postOrder(struct Node *node)
{
    if (node == NULL)
        return;

    // First we traverse left subtree
    postOrder(node->left);

    // After visiting left, traverse right subtree
    postOrder(node->right);

    // now we visit node
    printf("%d ", node->data);
}

int main()
{
    //Represent Tree
    //       1
    //      / \
    //     2   3
    //    / \   \
    //   4   5   6

    struct Node *root = createNode(1);
    root->left = createNode(2);
    root->right = createNode(3);
    root->left->left = createNode(4);
    root->left->right = createNode(5);
    root->right->right = createNode(6);
    postOrder(root);

    return 0;
}


