    using System;
using System.Collections.Generic;

// Node Structure
class Node
{
    public int data;
    public Node left;
    public Node right;

    public Node(int v)
    {
        data = v;
        left = null;
        right = null;
    }
}

class GFG
{
    static void postOrder(Node node, List<int> res)
    {
        if (node == null)
            return;

        // First we traverse left subtree
        postOrder(node.left, res);

        // After visiting left, traverse right subtree
        postOrder(node.right, res);

        // now we visit node
        res.Add(node.data);
    }

    static void Main()
    {
        //Represent Tree
        //       1
        //      / \
        //     2   3
